import static org.junit.Assert.*;

public class MutableDateTime_addMonths_TriageGen1Test {











    @Test
    public void testAddMonths_EndOfMonthAdjustment() {
        // Test leap year and month length adjustment
        // Jan 31 + 1 month (if logic allowed it) would be Feb 28/29.
        // However, since the code skips '1', we test with '2' to trigger the logic.
        MutableDateTime dt = new MutableDateTime(2024, 1, 31, 0, 0, 0, 0); // 2024 is leap year
        dt.addMonths(2); // Should go to March 31
        assertEquals(2024, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(31, dt.getDayOfMonth());

        MutableDateTime dt2 = new MutableDateTime(2023, 1, 31, 0, 0, 0, 0);
        dt2.addMonths(2); // Should go to March 31
        assertEquals(3, dt2.getMonthOfYear());
        assertEquals(31, dt2.getDayOfMonth());
    }
}
